import { useContext, useEffect, useState } from 'react';
import AuthContext from '../context/AuthContext';
import axios from 'axios';

function Dashboard() {
  const { user } = useContext(AuthContext);
  const [resumes, setResumes] = useState([]);

  useEffect(() => {
    async function load() {
      try {
        const res = await axios.get('http://localhost:5001/api/resume/my', { withCredentials: true });
        setResumes(res.data.data);
      } catch (err) {
        console.error(err);
      }
    }
    if (user) load();
  }, [user]);

  if (!user) return <div style={{ padding: 20 }}>Please login to view your dashboard</div>;

  return (
    <div className="page mt-10">
      <div className="container">
        <header className="mb-6">
          <h3 className="text-2xl">{user.name || user.email}'s Dashboard</h3>
          <p className="muted">Track your applications and match results.</p>
        </header>

        <div className="max-w-4xl mx-auto">
          {resumes.length === 0 ? (
            <div className="card text-center py-10">
              <p className="muted">No resumes uploaded yet. Start by uploading your profile.</p>
            </div>
          ) : (
            <div className="flex flex-col gap-4">
              {resumes.map(r => (
                <div key={r._id} className="card p-6 border-l-4" style={{ borderLeftColor: r.score >= 70 ? 'var(--success)' : (r.score >= 40 ? '#f59e0b' : 'var(--danger)') }}>
                  <div className="flex justify-between items-start mb-4">
                    <div>
                      <div className="flex items-center gap-2 mb-1">
                        <span className={`badge ${r.score >= 70 ? 'score-good' : (r.score >= 40 ? 'score-warn' : 'score-bad')}`}>
                          Score: {Math.round(r.score || 0)}%
                        </span>
                        <span className="badge bg-secondary">{r.interviewStatus}</span>
                      </div>
                      <p className="muted small">{r.createdAt ? new Date(r.createdAt).toLocaleString() : ''}</p>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <strong className="block text-sm mb-1">Matched Skills:</strong>
                      <div className="flex flex-wrap">
                        {(r.matchedSkills || r.skills || []).map((s, i) => (
                          <span key={i} className="badge bg-secondary">{s}</span>
                        ))}
                      </div>
                    </div>
                    <div>
                      <strong className="block text-sm mb-1">Missing Skills:</strong>
                      <div className="flex flex-wrap">
                        {(r.missingSkills || []).length > 0 ? (
                          (r.missingSkills || []).map((s, i) => (
                            <span key={i} className="badge bg-secondary missing">{s}</span>
                          ))
                        ) : (
                          <span className="text-sm muted">None identified</span>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
